import app from 'flarum/common/app';
import { flat as toFlat } from './jsonapi';

/** A sponsor as a giveaway or calendar shows it (the "Presented by" banner, the opt-in box). */

const TYPE = 'giveaway-sponsors';
function base() {
  return `${app.forum.attribute('apiUrl')}/${TYPE}`;
}
const flat = r => toFlat(r);

/** The sponsor's tracked link: counts the click for this campaign, then goes to its website. */
export function trackedLink(slug, campaign) {
  const url = `${app.forum.attribute('baseUrl')}/giveaways/go/${encodeURIComponent(slug)}`;
  return campaign ? `${url}?c=${campaign.kind}-${campaign.id}` : url;
}
export function listSponsors() {
  return app.request({
    method: 'GET',
    url: base(),
    params: {
      page: {
        limit: 100
      }
    }
  }).then(r => r.data.map(flat));
}
export function showSponsor(slugOrId) {
  return app.request({
    method: 'GET',
    url: `${base()}/${encodeURIComponent(String(slugOrId))}`
  }).then(r => flat(r.data));
}
export function saveSponsor(attributes, id) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: id ? `${base()}/${id}` : base(),
    body: {
      data: {
        type: TYPE,
        ...(id ? {
          id: String(id)
        } : {}),
        attributes
      }
    }
  }).then(r => flat(r.data));
}
export function deleteSponsor(id) {
  return app.request({
    method: 'DELETE',
    url: `${base()}/${id}`
  });
}

/** Tick (true) or untick the box: share my email with this campaign's sponsor. */
export function setConsent(campaign, campaignId, on) {
  return app.request({
    method: 'POST',
    url: `${base()}/consent`,
    body: {
      campaign,
      campaignId,
      on
    }
  }).then(r => r.meta.consented);
}
export function myConsents() {
  return app.request({
    method: 'GET',
    url: `${base()}/consents`
  }).then(r => r.meta.consents);
}

/** A new secret report link; the only time it is shown. */
export function createReportLink(id) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/report-link`
  }).then(r => r.meta.reportUrl);
}
export function revokeReportLink(id) {
  return app.request({
    method: 'DELETE',
    url: `${base()}/${id}/report-link`
  });
}
export function eraseOptIns(id) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/erase`
  }).then(r => r.meta.erased);
}

/** Downloads the opted-in members as a CSV file (managers). */
export function exportOptIns(sponsor) {
  return app.request({
    method: 'POST',
    url: `${base()}/${sponsor.id}/export`,
    deserialize: text => text,
    responseType: 'text'
  }).then(csv => {
    const link = document.createElement('a');
    link.href = URL.createObjectURL(new Blob([csv], {
      type: 'text/csv'
    }));
    link.download = `${sponsor.slug}-opt-ins.csv`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  });
}
flarum.reg.add('ernestdefoe-giveaways', 'common/sponsors', { trackedLink: trackedLink,listSponsors: listSponsors,showSponsor: showSponsor,saveSponsor: saveSponsor,deleteSponsor: deleteSponsor,setConsent: setConsent,myConsents: myConsents,createReportLink: createReportLink,revokeReportLink: revokeReportLink,eraseOptIns: eraseOptIns,exportOptIns: exportOptIns, });